
-- Batch 11: Remaining recipes - Senegal, Sierra Leone, Somalia, South Africa, South Korea, Spain, Sudan, Syria, Tanzania, Thailand, Turkey, Tunisia, Uganda
UPDATE recipes SET continent = 'South America', history = 'Ceviche is Peru''s national dish, featuring raw fish "cooked" in citrus juice, a technique dating back to the Moche civilization (200 BCE). The addition of lime juice after Spanish colonization evolved the dish. Peruvian ceviche was inscribed on UNESCO''s Representative List of Intangible Cultural Heritage in 2023.' WHERE slug = 'ceviche-pe';

UPDATE recipes SET continent = 'Asia', history = 'Pakoras are South Asian fritters made by dipping vegetables in seasoned chickpea flour batter and deep-frying. Pakistani pakoras, enjoyed especially during Ramadan iftar, feature vibrant spicing with cumin, coriander, and chili. This street food represents the subcontinent''s ancient frying traditions.' WHERE slug = 'pakoras-pk';

UPDATE recipes SET continent = 'Africa', history = 'Isombe is a Central African dish of mashed cassava leaves cooked with eggplant and palm oil, shared between Rwanda and DRC. This nutritious preparation represents the Great Lakes region''s reliance on cassava as both root and leaf vegetable, maximizing the plant''s nutritional potential.' WHERE slug = 'isombe-rwanda-drc';

UPDATE recipes SET continent = 'Europe', history = 'Kanelbullar (Cinnamon Buns) are Sweden''s national pastry, celebrated on October 4th—Kanelbullens Dag. Swedish baking culture dates back to the 18th century when spices became affordable. These cardamom-scented rolls represent the Swedish fika tradition of coffee and pastry breaks.' WHERE slug = 'kanelbullar-se';

UPDATE recipes SET continent = 'Europe', history = 'Pumpkin Lentil Soup reflects Sweden''s embrace of healthy, plant-forward cuisine. Swedish food culture has increasingly incorporated global flavors while maintaining the Nordic emphasis on wholesome, seasonal ingredients. This warming soup represents modern Scandinavian home cooking.' WHERE slug = 'pumpkin-lentil-soup-se';

UPDATE recipes SET continent = 'Africa', history = 'Bissap Juice is a refreshing hibiscus flower drink popular across Senegal and West Africa. The deep red beverage, known as zobo in Nigeria, has been consumed for centuries. Rich in vitamin C and antioxidants, bissap represents the traditional African knowledge of medicinal plants as both food and medicine.' WHERE slug = 'bissap-juice';

UPDATE recipes SET continent = 'Africa', history = 'Soupou Kandja is a Senegalese okra soup that showcases the importance of this African-origin vegetable in West African cuisine. Okra, cultivated in Africa for millennia, forms the base of countless soups across the continent. This Senegalese version is rich with seafood and palm oil.' WHERE slug = 'soupou-kandja';

UPDATE recipes SET continent = 'Africa', history = 'Tchep Bou Dien (Thieboudienne) is Senegal''s UNESCO-inscribed national dish. Created in the 19th century in Saint-Louis, this fish and rice masterpiece uses just one pot to create layers of complex flavors. It represents the genius of Wolof cuisine and is considered West Africa''s most influential recipe.' WHERE slug = 'tchep-bou-dien';

UPDATE recipes SET continent = 'Africa', history = 'Thiakry (Degue) is a Senegalese fermented millet dessert mixed with sweetened yogurt and vanilla. This refreshing treat reflects the ancient Sahelian tradition of fermenting grains and the dairy culture of the Fulani pastoralists. It''s a popular dessert served at celebrations and during Ramadan.' WHERE slug = 'thiakry-degue-senegal';

UPDATE recipes SET continent = 'Africa', history = 'Thiebou Yapp is the meat version of Senegal''s famous thieboudienne, featuring lamb or beef instead of fish. This inland adaptation represents how Senegalese cuisine varies by geography, with coastal regions favoring fish and interior regions using meat, while maintaining the same aromatic rice preparation.' WHERE slug = 'thiebou-yapp-senegal';

UPDATE recipes SET continent = 'Africa', history = 'Yassa Poisson is a Senegalese marinated fish dish featuring a tangy onion and lemon sauce. Yassa, from the Casamance region, is one of Senegal''s most beloved cooking styles. The technique of marinating fish in citrus before cooking reflects the Portuguese culinary influence on Senegalese coastal cuisine.' WHERE slug = 'yassa-poisson-senegal';

UPDATE recipes SET continent = 'Africa', history = 'Yassa Guinar (Chicken Yassa) is a beloved Senegalese-Gambian dish of marinated chicken in caramelized onion and lemon sauce. Originating from the Casamance region, yassa is one of West Africa''s most popular dishes. The tangy, savory flavor profile has made it a global ambassador for Senegalese cuisine.' WHERE slug = 'yassa-guinar-chicken-senegal-gambia';

UPDATE recipes SET continent = 'Africa', history = 'Ladob is a sweet Seychellois dessert made with ripe plantains or sweet potatoes cooked in coconut milk with vanilla and nutmeg. This dish reflects the Seychelles'' unique Creole cuisine, blending African, French, Indian, and Chinese culinary traditions in the heart of the Indian Ocean.' WHERE slug = 'ladob-sweet-seychelles';

UPDATE recipes SET continent = 'Africa', history = 'Plasas (Leafy Greens Stew) is Sierra Leone''s quintessential vegetable dish, made with pounded cassava leaves cooked in palm oil. This nutritious stew represents the country''s deep connection to leafy greens and the West African tradition of transforming simple ingredients into rich, flavorful dishes.' WHERE slug = 'plasas-leafy-greens-stew-sierra-leone';

UPDATE recipes SET continent = 'Africa', history = 'Cocoyam Pottage is a hearty Sierra Leonean stew featuring cocoyam (taro), a root vegetable cultivated across West Africa for centuries. This one-pot dish represents the tradition of combining tubers with leafy greens and protein for a complete, nourishing meal.' WHERE slug = 'cocoyam-pottage-sl';

UPDATE recipes SET continent = 'Africa', history = 'Bissap (Hibiscus Tea) is a beloved Senegalese refreshment made from dried hibiscus flowers. This vibrant red drink, rich in antioxidants, is enjoyed across West Africa. In Senegal, bissap is served at celebrations and daily as a refreshing alternative to commercially produced beverages.' WHERE slug = 'bissap-sn';

UPDATE recipes SET continent = 'Africa', history = 'Sambusa (Somali Samosa) arrived in Somalia through centuries of trade with India and the Arab world. Somali sambusas feature distinctive fillings with xawaash spice blend and are essential during Ramadan iftar. They represent the culinary crossroads of the Horn of Africa.' WHERE slug = 'sambusa-so';

UPDATE recipes SET continent = 'Africa', history = 'Bariis Iskukaris is a fragrant Somali spiced rice dish that reflects the country''s position on ancient trade routes. The blend of cardamom, cinnamon, and cumin shows Arab and Indian influences, while the cooking technique is distinctly Somali. It''s the centerpiece of Somali celebrations.' WHERE slug = 'bariis-iskukaris-somalia';

UPDATE recipes SET continent = 'Africa', history = 'Cambuulo iyo Subag is a traditional Somali dish of adzuki beans with ghee. This nutritious, protein-rich dish has sustained Somali communities for generations. The use of ghee (subag) reflects the pastoral dairy traditions of Somali nomadic culture.' WHERE slug = 'cambuulo-iyo-subag-somalia';

UPDATE recipes SET continent = 'Africa', history = 'Maraq Fahfah is a Somali coastal aromatic soup featuring a complex blend of spices. This dish represents the sophisticated culinary traditions of Somalia''s coastal communities, influenced by centuries of maritime trade across the Indian Ocean.' WHERE slug = 'maraq-fahfah-somalia-coast';

UPDATE recipes SET continent = 'Africa', history = 'Bobotie is South Africa''s national dish, a spiced ground meat bake topped with an egg custard. Its origins trace to the Cape Malay community who blended Indonesian, Dutch, and African flavors. First recorded in a 1609 Dutch cookbook, bobotie represents the multicultural roots of South African cuisine.' WHERE slug = 'bobotie-south-africa';

UPDATE recipes SET continent = 'Africa', history = 'Bobotie-Stuffed Sweet Potatoes is a modern fusion combining South Africa''s national dish with the nutritious sweet potato. This creative adaptation reflects contemporary South African cooking that honors traditional flavors while embracing healthy, modern presentation styles.' WHERE slug = 'bobotie-stuffed-sweet-potatoes';

UPDATE recipes SET continent = 'Africa', history = 'Chakalaka is a spicy South African vegetable relish created by mineworkers in Johannesburg''s gold mining hostels. This fiery mix of peppers, tomatoes, and beans represents the resilience and creativity of South Africa''s urban working-class communities and has become a national favorite at every braai.' WHERE slug = 'chakalaka-south-africa';

UPDATE recipes SET continent = 'Africa', history = 'Dombolo (Steamed Dumplings) are a South African comfort food, fluffy steamed bread dumplings served with stews. This dish represents the Zulu and Xhosa home cooking traditions, where dombolo provides the perfect accompaniment to rich, flavorful meat and vegetable stews.' WHERE slug = 'dombolo-steamed-south-africa';

UPDATE recipes SET continent = 'Africa', history = 'Skilpadjies are a traditional South African braai delicacy of seasoned lamb liver wrapped in caul fat and grilled. The name means "little tortoises" in Afrikaans, referring to their appearance. This dish represents the nose-to-tail cooking traditions of South African farm culture.' WHERE slug = 'skilpadjies-south-africa';
